let deferredPrompt; function installApp() { deferredPrompt.prompt(), deferredPrompt.userChoice.then((e => { e.outcome, deferredPrompt = null })) } window.addEventListener("beforeinstallprompt", (e => { e.preventDefault(), deferredPrompt = e, document.getElementById("installModal").classList.remove("hidden"); document.getElementById("installButton").addEventListener("click", (() => { installApp() })) }));